"""Workspace toolkit — project scaffolding."""

import contextlib
from pathlib import Path

import typer

from forgekit.output import create_table, get_console, print_json
from forgekit.utils import run_command

app = typer.Typer(help="Project workspace scaffolding.", no_args_is_help=True)
console = get_console()

TEMPLATES = {
    "python": {
        "description": "Python project with src layout, pyproject.toml, README, .gitignore",
        "files": {
            "README.md": "# {name}\n\nProject generated by ForgeKit.\n",
            ".gitignore": "__pycache__/\n*.pyc\n.venv/\nvenv/\ndist/\nbuild/\n*.egg-info/\n.env\n.pytest_cache/\n.mypy_cache/\n",
            "pyproject.toml": '[project]\nname = "{name}"\nversion = "0.1.0"\ndescription = ""\nrequires-python = ">=3.11"\ndependencies = []\n\n[build-system]\nrequires = ["hatchling"]\nbuild-backend = "hatchling.build"\n',
            "src/{name}/__init__.py": '__version__ = "0.1.0"\n',
            "src/{name}/__main__.py": 'def main():\n    print("Hello from {name}")\n\nif __name__ == "__main__":\n    main()\n',
            "tests/test_example.py": "def test_example():\n    assert True\n",
        },
        "dirs": ["src/{name}", "tests"],
    },
    "node": {
        "description": "Node.js project with package.json, README, .gitignore (no npm install)",
        "files": {
            "README.md": "# {name}\n\nProject generated by ForgeKit.\n",
            ".gitignore": "node_modules/\ndist/\n.env\nnpm-debug.log*\n",
            "package.json": '{{\n  "name": "{name}",\n  "version": "0.1.0",\n  "description": "",\n  "main": "index.js",\n  "scripts": {{\n    "start": "node index.js",\n    "test": "echo \\"No tests\\" && exit 0"\n  }},\n  "keywords": [],\n  "license": "MIT"\n}}\n',
            "index.js": 'console.log("Hello from {name}");\n',
        },
        "dirs": [],
    },
    "generic": {
        "description": "Generic project with README and .gitignore",
        "files": {
            "README.md": "# {name}\n\nProject generated by ForgeKit.\n",
            ".gitignore": "*.log\n.env\n.DS_Store\n",
        },
        "dirs": [],
    },
}

GITIGNORE_TEMPLATES = {
    "python": "__pycache__/\n*.py[cod]\n.venv/\nvenv/\ndist/\nbuild/\n*.egg-info/\n.env\n.pytest_cache/\n.mypy_cache/\n.ruff_cache/\n",
    "node": "node_modules/\ndist/\n.env\nnpm-debug.log*\ncoverage/\n",
    "go": "bin/\n*.exe\nvendor/\n",
    "generic": "*.log\n.env\n.DS_Store\n",
}


@app.command("create")
def create_cmd(
    name: str = typer.Argument(..., help="Project name (directory name)"),
    template: str = typer.Option(
        "python", "--template", "-t", help="Template: python, node, generic"
    ),
    path: str = typer.Option(".", "--path", "-p", help="Parent directory"),
    git: bool = typer.Option(False, "--git", help="Initialize git repository"),
    force: bool = typer.Option(False, "--force", help="Overwrite if exists (use carefully)"),
    json: bool = typer.Option(False, "--json", help="Output as JSON"),
) -> None:
    """Create a new project from a template."""
    if template not in TEMPLATES:
        console.print(f"[red]Unknown template: {template}. Available: {', '.join(TEMPLATES)}[/red]")
        raise typer.Exit(1)

    parent = Path(path).resolve()
    if not parent.exists():
        console.print(f"[red]Parent path not found: {parent}[/red]")
        raise typer.Exit(1)

    dest = parent / name
    # Sanitize name: allow alphanum, -, _, .
    import re

    if not re.match(r"^[A-Za-z0-9._-]+$", name):
        console.print(f"[red]Invalid project name: {name}. Use letters, numbers, -, _, .[/red]")
        raise typer.Exit(1)

    if dest.exists() and not force:
        console.print(
            f"[red]Destination already exists: {dest}. Use --force to overwrite (files will be skipped if present).[/red]"
        )
        raise typer.Exit(1)

    tmpl = TEMPLATES[template]
    created_files: list[str] = []
    skipped: list[str] = []

    dest.mkdir(parents=True, exist_ok=True)

    # Create dirs
    for d in tmpl.get("dirs", []):  # type: ignore
        dir_name = d.format(name=name.lower().replace("-", "_") if template == "python" else name)
        (dest / dir_name).mkdir(parents=True, exist_ok=True)

    # Create files
    for rel, content in tmpl["files"].items():  # type: ignore
        fname = rel.format(name=name.lower().replace("-", "_") if template == "python" else name)
        fpath = dest / fname
        if fpath.exists() and not force:
            skipped.append(str(fpath))
            continue
        fpath.parent.mkdir(parents=True, exist_ok=True)
        # Handle JSON escaping: package.json template has doubled braces
        text = content.format(name=name)
        fpath.write_text(text)
        created_files.append(str(fpath))

    # Git init if requested
    git_msg = ""
    if git:
        try:
            # Confirm if interactive? Spec says initialize optionally after confirmation, but --git flag implies consent
            r = run_command(["git", "init"], cwd=dest)
            if r.returncode == 0:
                git_msg = "Git initialized."
            else:
                git_msg = f"Git init failed: {r.stderr[:100]}"
        except FileNotFoundError:
            git_msg = "Git not found — skipping git init."
        except Exception as e:
            git_msg = f"Git init error: {e}"

    if json:
        print_json(
            {
                "project": str(dest),
                "template": template,
                "created": created_files,
                "skipped": skipped,
                "git": git_msg,
            }
        )
        return

    console.print(f"[green]✓ Project created: {dest} (template: {template})[/green]")
    for f in created_files:
        console.print(f"  [dim]+[/dim] {f}")
    if skipped:
        console.print(f"[yellow]Skipped existing files: {len(skipped)}[/yellow]")
    if git_msg:
        console.print(f"[dim]{git_msg}[/dim]")
    console.print("[dim]No package installation was performed.[/dim]")


@app.command("templates")
def templates_cmd(
    json: bool = typer.Option(False, "--json", help="Output as JSON"),
) -> None:
    """List available templates."""
    if json:
        print_json({k: v["description"] for k, v in TEMPLATES.items()})
        return

    table = create_table(title="Available Templates")
    table.add_column("Template", style="cyan")
    table.add_column("Description", style="white")
    table.add_column("Files", style="dim")
    for k, v in TEMPLATES.items():
        table.add_row(k, v["description"], ", ".join(list(v["files"].keys())[:4]))  # type: ignore
    console.print(table)
    console.print("[dim]Use: forge workspace create NAME --template TEMPLATE[/dim]")


@app.command("inspect")
def inspect_cmd(
    target: str = typer.Argument(..., help="Path to inspect"),
    json: bool = typer.Option(False, "--json", help="Output as JSON"),
) -> None:
    """Inspect a project directory."""
    p = Path(target).resolve()
    if not p.exists():
        console.print(f"[red]Path not found: {p}[/red]")
        raise typer.Exit(1)

    info: dict[str, object] = {"path": str(p), "is_dir": p.is_dir(), "is_file": p.is_file()}
    if p.is_dir():
        try:
            entries = list(p.iterdir())
            info["entries"] = [e.name for e in entries[:30]]
            info["entry_count"] = len(entries)
            # Detect template type
            if (p / "pyproject.toml").exists() or (p / "setup.py").exists():
                info["detected_template"] = "python"
            elif (p / "package.json").exists():
                info["detected_template"] = "node"
            else:
                info["detected_template"] = "generic"
            info["has_git"] = (p / ".git").exists()
            info["has_readme"] = (p / "README.md").exists()
            info["has_gitignore"] = (p / ".gitignore").exists()
            # Size
            total = 0
            for f in p.rglob("*"):
                if f.is_file():
                    with contextlib.suppress(OSError):
                        total += f.stat().st_size
            from forgekit.utils import format_bytes

            info["total_size"] = total
            info["total_size_human"] = format_bytes(total)
        except PermissionError as e:
            info["error"] = str(e)

    if json:
        print_json(info)
        return

    table = create_table(title=f"Workspace: {p}")
    table.add_column("Property", style="cyan")
    table.add_column("Value", style="white")
    for k, v in info.items():
        if isinstance(v, list):
            v = ", ".join(str(x) for x in v[:10])
        table.add_row(k, str(v)[:100])
    console.print(table)
